const express = require('express');
const { Pool } = require('pg');
const { OpenAIEmbeddings } = require('@langchain/openai');

const pool = new Pool();
const embeddings = new OpenAIEmbeddings();
const app = express();
app.use(express.json());

app.post('/api/documents/:documentId/rag-context', async (req, res) => {
  const { documentId } = req.params;
  const { query } = req.body;

  if (!query) return res.status(400).json({ error: 'Missing search query' });

  // Verify document ownership and tenant access rights in relational schema
  const docCheck = await pool.query(
    'SELECT id FROM documents WHERE id = $1 AND company_id = $2',
    [documentId, req.user.companyId]
  );

  if (docCheck.rows.length === 0) {
    return res.status(404).json({ error: 'Document not found or access denied' });
  }

  const queryEmbedding = await embeddings.embedQuery(query);
  const vectorString = `[${queryEmbedding.join(',')}]`;

  const { rows } = await pool.query(
    `SELECT id, chunk_content, 1 - (embedding <=> $1) AS similarity
     FROM document_embeddings
     WHERE document_id = $2
     ORDER BY similarity DESC
     LIMIT 5`,
    [vectorString, documentId]
  );

  return res.json({ chunks: rows });
});

module.exports = app;
